<template>
  <section class="support-page" :class="{ embedded: adminMode }">
    <header class="support-heading"><div><p class="eyebrow">TAVIVU CARE</p><h1>{{ adminMode ? 'Hỗ trợ khách hàng' : 'Trung tâm hỗ trợ' }}</h1><p>Trao đổi cùng TaVivu về chuyến đi và đơn đặt tour của bạn.</p></div><button v-if="!adminMode" class="primary" @click="openNew">Gửi yêu cầu mới</button></header>
    <p v-if="error" class="support-error" role="alert">{{ error }} <button @click="refreshAll">Thử lại</button></p>
    <div class="support-layout">
      <aside class="thread-list">
        <label class="filter">Trạng thái yêu cầu<select v-model="filter"><option value="">Tất cả</option><option value="OPEN">Mới tiếp nhận</option><option value="IN_PROGRESS">Đang xử lý</option><option value="RESOLVED">Đã giải quyết</option></select></label>
        <p v-if="loadingList">Đang tải yêu cầu…</p>
        <p v-else-if="!threads.length" class="empty">Chưa có yêu cầu hỗ trợ{{ filter ? ' ở trạng thái này' : '' }}.</p>
        <button v-for="item in threads" :key="item.ConversationID" class="thread-item" :class="{ active: selectedId === item.ConversationID }" @click="selectThread(item.ConversationID)">
          <div class="thread-top"><strong>{{ item.Subject }}</strong><span v-if="Number(item.UnreadCount)" class="unread">{{ item.UnreadCount }}</span></div>
          <small v-if="adminMode">{{ item.CustomerName }}</small><span class="preview">{{ item.LastMessage }}</span>
          <div class="thread-meta"><span class="status" :class="item.Status">{{ statusName(item.Status) }}</span><small>{{ date(item.UpdatedAt) }}</small></div>
        </button>
        <button v-if="hasMore" class="load-more" @click="loadList(true)">Xem thêm yêu cầu</button>
      </aside>
      <main class="conversation-pane">
        <form v-if="creating && !adminMode" class="new-request" @submit.prevent="createThread">
          <h2>Yêu cầu hỗ trợ mới</h2><label>Chủ đề<select v-model="draft.category"><option value="TOUR">Tư vấn tour</option><option value="PAYMENT">Thanh toán</option><option value="CANCELLATION">Hủy / hoàn tiền</option><option value="OTHER">Vấn đề khác</option></select></label>
          <label>Đơn đặt tour liên quan <span>(không bắt buộc)</span><select v-model="draft.bookingId"><option value="">Không gắn đơn đặt tour</option><option v-for="b in bookings" :key="b.BookingID" :value="b.BookingID">{{ b.Title }} · {{ b.BookingID }}</option></select></label>
          <label>Tiêu đề<input v-model="draft.subject" required maxlength="150" placeholder="Bạn cần hỗ trợ vấn đề gì?" /></label>
          <label>Nội dung<textarea v-model="draft.content" required maxlength="2000" rows="6" placeholder="Mô tả chi tiết để chúng tôi hỗ trợ bạn…" /></label><small>{{ draft.content.length }}/2000 ký tự</small>
          <button class="primary" :disabled="sending || !draft.subject.trim() || !draft.content.trim()">{{ sending ? 'Đang gửi…' : 'Gửi yêu cầu' }}</button>
        </form>
        <div v-else-if="loadingThread" class="empty">Đang tải hội thoại…</div>
        <template v-else-if="thread">
          <header class="conversation-header"><div><h2>{{ thread.Subject }}</h2><p>{{ categoryName(thread.Category) }}<template v-if="adminMode"> · {{ thread.CustomerName }}</template></p></div><span class="status" :class="thread.Status">{{ statusName(thread.Status) }}</span></header>
          <div v-if="thread.Booking" class="booking-context"><strong>{{ thread.Booking.Title }}</strong><span>{{ thread.Booking.BookingID }} · {{ bookingStatus(thread.Booking.Status) }}</span><span v-if="adminMode">{{ thread.Booking.ContactName }} · {{ thread.Booking.ContactPhone }}</span><a v-else :href="`/bookings/${encodeURIComponent(thread.Booking.BookingID)}`">Chi tiết đơn đặt tour →</a></div>
          <div v-if="adminMode" class="admin-actions"><label>Trạng thái xử lý<select :value="thread.Status" :disabled="updatingStatus" @change="changeStatus($event.target.value)"><option value="OPEN">Mới tiếp nhận</option><option value="IN_PROGRESS">Đang xử lý</option><option value="RESOLVED">Đã giải quyết</option></select></label><small>Việc hủy hoặc hoàn tiền được xử lý tại mục Đơn đặt chỗ.</small></div>
          <div ref="messagePane" class="messages" role="log" aria-label="Tin nhắn hỗ trợ" aria-live="polite">
            <button v-if="hasOlder" class="load-more" :disabled="loadingOlder" @click="loadOlder">{{ loadingOlder ? 'Đang tải…' : 'Xem tin nhắn trước' }}</button>
            <article v-for="m in messages" :key="m.MessageID" class="message-row" :class="{ mine: adminMode ? m.SenderRole === 'ADMIN' : m.SenderRole === 'USER' }"><div class="bubble"><strong>{{ m.SenderRole === 'ADMIN' ? 'TaVivu · ' + m.SenderName : m.SenderName }}</strong><p>{{ m.Content }}</p><small>{{ date(m.CreatedAt) }}</small></div></article>
          </div>
          <p v-if="thread.Status === 'RESOLVED'" class="resolved-note">Yêu cầu đã được giải quyết. Gửi tin nhắn mới nếu bạn cần hỗ trợ thêm.</p>
          <form class="reply-form" @submit.prevent="sendMessage"><label class="sr-only" for="support-reply">Nội dung tin nhắn</label><textarea id="support-reply" v-model="reply" rows="2" maxlength="2000" required placeholder="Nhập tin nhắn…" :disabled="sending" /><div><small>{{ reply.length }}/2000</small><button class="primary" :disabled="sending || !reply.trim()">{{ sending ? 'Đang gửi…' : 'Gửi tin nhắn' }}</button></div></form>
        </template>
        <div v-else class="empty"><h2>Chúng tôi luôn sẵn sàng hỗ trợ</h2><p>{{ adminMode ? 'Chọn yêu cầu bên trái để bắt đầu phản hồi.' : 'Chọn một hội thoại hoặc gửi yêu cầu hỗ trợ mới.' }}</p><button v-if="!adminMode" class="primary" @click="openNew">Gửi yêu cầu</button></div>
      </main>
    </div>
  </section>
</template>
<script setup>
import { ref, watch, onMounted, onUnmounted, nextTick } from 'vue';
import { supportRequest, ownBookings } from '../services/support';
const props=defineProps({adminMode:Boolean,initialBooking:{type:String,default:''}});
const threads=ref([]),filter=ref(''),selectedId=ref(''),thread=ref(null),messages=ref([]),creating=ref(false),error=ref(''),loadingList=ref(false),loadingThread=ref(false),sending=ref(false),updatingStatus=ref(false),hasMore=ref(false),hasOlder=ref(false),loadingOlder=ref(false),reply=ref(''),bookings=ref([]),messagePane=ref(null);
const draft=ref({subject:'',content:'',category:'TOUR',bookingId:''});
let timer,disposed=false,version=0,polling=false,listVersion=0,pendingMessage=null;
const statusName=s=>({OPEN:'Mới tiếp nhận',IN_PROGRESS:'Đang xử lý',RESOLVED:'Đã giải quyết'}[s]||s);
const categoryName=s=>({TOUR:'Tư vấn tour',PAYMENT:'Thanh toán',CANCELLATION:'Hủy / hoàn tiền',OTHER:'Vấn đề khác'}[s]||s);
const bookingStatus=s=>({PENDING:'Chờ thanh toán',PAID:'Đã thanh toán',COMPLETED:'Đã hoàn thành',CANCELLED:'Đã hủy',REFUNDING:'Chờ hoàn tiền',REFUNDED:'Đã hoàn tiền'}[s]||s);
const date=s=>s?new Date(s).toLocaleString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh',dateStyle:'short',timeStyle:'short'}):'';
const notify=()=>window.dispatchEvent(new Event('support-read'));
async function loadList(more=false){
 const ticket=++listVersion;const offset=more?threads.value.length:0;loadingList.value=!threads.value.length;
 try{const r=await supportRequest(`/support?status=${encodeURIComponent(filter.value)}&offset=${offset}`);if(disposed||ticket!==listVersion)return;threads.value=more?[...threads.value,...r.data]:r.data;hasMore.value=r.hasMore;}finally{if(ticket===listVersion)loadingList.value=false;}
}
async function fetchThread(id,replace=false){
 const ticket=version;const pane=messagePane.value,follow=!pane||pane.scrollHeight-pane.scrollTop-pane.clientHeight<80;
 const r=await supportRequest(`/support/${encodeURIComponent(id)}`);if(disposed||ticket!==version||selectedId.value!==id)return;
 thread.value=r.data;
 if(replace){messages.value=r.data.messages;hasOlder.value=r.data.hasOlder;}
 else{const merged=new Map(messages.value.map(m=>[m.MessageID,m]));r.data.messages.forEach(m=>merged.set(m.MessageID,m));messages.value=[...merged.values()].sort((a,b)=>a.CreatedAt.localeCompare(b.CreatedAt)||a.MessageID.localeCompare(b.MessageID));}
 notify();await nextTick();if((replace||follow)&&messagePane.value)messagePane.value.scrollTop=messagePane.value.scrollHeight;
}
async function selectThread(id){version++;selectedId.value=id;creating.value=false;thread.value=null;messages.value=[];reply.value='';pendingMessage=null;loadingThread.value=true;error.value='';const ticket=version;try{await fetchThread(id,true);await loadList();}catch(e){if(ticket===version)error.value=e.message;}finally{if(ticket===version)loadingThread.value=false;}}
function openNew(){version++;selectedId.value='';thread.value=null;creating.value=true;error.value='';loadingThread.value=false;}
async function createThread(){if(sending.value)return;sending.value=true;error.value='';try{const r=await supportRequest('/support',{method:'POST',body:JSON.stringify(draft.value)});draft.value={subject:'',content:'',category:'TOUR',bookingId:''};await selectThread(r.conversationId);}catch(e){error.value=e.message;}finally{sending.value=false;}}
async function sendMessage(){if(sending.value||!reply.value.trim())return;const id=selectedId.value,content=reply.value.trim();if(!pendingMessage||pendingMessage.content!==content||pendingMessage.id!==id)pendingMessage={id,content,messageId:crypto.randomUUID()};const pending=pendingMessage;sending.value=true;error.value='';try{await supportRequest(`/support/${encodeURIComponent(id)}/messages`,{method:'POST',body:JSON.stringify({content,messageId:pending.messageId})});if(selectedId.value===id){reply.value='';pendingMessage=null;await fetchThread(id);await nextTick();if(messagePane.value)messagePane.value.scrollTop=messagePane.value.scrollHeight;}await loadList();}catch(e){error.value=e.message;}finally{sending.value=false;}}
async function changeStatus(status){const id=selectedId.value;updatingStatus.value=true;error.value='';try{await supportRequest(`/support/${encodeURIComponent(id)}/status`,{method:'PATCH',body:JSON.stringify({status})});if(id===selectedId.value)await fetchThread(id);await loadList();}catch(e){error.value=e.message;}finally{updatingStatus.value=false;}}
async function loadOlder(){if(!messages.value.length||loadingOlder.value)return;const id=selectedId.value,ticket=version,pane=messagePane.value,oldHeight=pane?.scrollHeight||0;loadingOlder.value=true;try{const r=await supportRequest(`/support/${encodeURIComponent(id)}?before=${messages.value[0].MessageID}`);if(ticket!==version)return;messages.value=[...r.data.messages,...messages.value];hasOlder.value=r.data.hasOlder;notify();await nextTick();if(pane)pane.scrollTop=pane.scrollHeight-oldHeight;}catch(e){error.value=e.message;}finally{loadingOlder.value=false;}}
async function refreshAll(){if(polling||disposed)return;polling=true;try{if(selectedId.value&&!loadingThread.value&&!sending.value)await fetchThread(selectedId.value);await loadList();error.value='';}catch(e){error.value=e.message;}finally{polling=false;}}
watch(filter,()=>{loadList().catch(e=>error.value=e.message);});
watch(()=>props.initialBooking,id=>{if(id){draft.value.bookingId=id;openNew();}});
onMounted(async()=>{if(props.initialBooking){draft.value.bookingId=props.initialBooking;openNew();}await refreshAll();if(!props.adminMode){try{bookings.value=await ownBookings();}catch(e){error.value=e.message;}}if(!disposed)timer=setInterval(()=>{if(!document.hidden)refreshAll();},5000);});
onUnmounted(()=>{disposed=true;version++;clearInterval(timer);});
</script>
<style scoped>
.support-page{max-width:1200px;margin:0 auto;padding:120px 24px 60px;color:#17332e}.support-page.embedded{padding:28px;max-width:none}.support-heading{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:28px}.support-heading h1{font-size:2rem;margin:4px 0 10px}.support-heading p{color:#64748b}.eyebrow{font-size:.75rem;letter-spacing:.18em;font-weight:700;color:#00856f!important}.support-layout{display:grid;grid-template-columns:320px minmax(0,1fr);background:white;border:1px solid #dce8e5;border-radius:24px;overflow:hidden;box-shadow:0 12px 40px #17332e0a;min-height:620px}.thread-list{border-right:1px solid #e2e8f0;padding:18px;background:#f8fbfa;max-height:800px;overflow:auto}.filter,.new-request label,.admin-actions label{display:flex;flex-direction:column;gap:8px;font-size:.9rem;font-weight:600}.filter{margin-bottom:20px}.support-page button,.support-page input,.support-page textarea,.support-page select{font:inherit}.support-page button{cursor:pointer;border:1px solid #d4e2de;border-radius:10px;padding:10px 14px;background:white;color:inherit}.support-page button:disabled{opacity:.6;cursor:not-allowed}.support-page .primary{background:#007d68;color:white;border-color:#007d68;font-weight:700}.support-page input,.support-page select,.support-page textarea{padding:12px;border:1px solid #cbd5e1;border-radius:10px;min-width:0;max-width:100%;background:white;color:#17332e}.support-page textarea{resize:vertical}.support-page :focus-visible{outline:2px solid #0d9488;outline-offset:3px}.thread-item{width:100%;text-align:left;display:flex;flex-direction:column;gap:8px;margin-bottom:10px}.thread-item.active{border-color:#0d9488;background:#e9f7f3}.thread-top{display:flex;justify-content:space-between;gap:8px;overflow-wrap:anywhere}.preview{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:100%;font-size:.85rem;color:#64748b}.thread-meta{display:flex;gap:6px;align-items:center;justify-content:space-between;flex-wrap:wrap}.thread-meta small{font-size:.7rem;color:#64748b}.unread{border-radius:20px;background:#007d68;color:white;font-size:.75rem;padding:2px 7px;align-self:start}.status{display:inline-block;padding:5px 9px;border-radius:20px;font-size:.75rem;white-space:nowrap;background:#fff2d5;color:#94580b}.status.IN_PROGRESS{background:#e8f1ff;color:#2455a4}.status.RESOLVED{background:#e0f4e7;color:#25623c}.conversation-pane{min-width:0;display:flex;flex-direction:column}.conversation-header{padding:24px;display:flex;justify-content:space-between;gap:12px;align-items:start;border-bottom:1px solid #e2e8f0}.conversation-header h2{font-size:1.2rem;overflow-wrap:anywhere;margin:0 0 6px}.conversation-header p{font-size:.85rem;color:#64748b}.booking-context{margin:16px 24px 0;padding:14px;background:#eff8f5;border-radius:12px;display:flex;flex-direction:column;gap:6px;font-size:.85rem}.booking-context a{color:#007d68}.admin-actions{padding:16px 24px;display:flex;flex-direction:column;gap:10px}.admin-actions small{color:#64748b}.messages{height:360px;overflow:auto;padding:20px 24px;overscroll-behavior:contain}.message-row{display:flex;margin-bottom:16px}.message-row.mine{justify-content:flex-end}.bubble{max-width:85%;padding:14px 16px;background:#f1f5f9;border-radius:16px 16px 16px 4px;overflow-wrap:anywhere}.mine .bubble{background:#e0f3ed;border-radius:16px 16px 4px 16px}.bubble strong{font-size:.8rem}.bubble p{white-space:pre-wrap;line-height:1.6;margin:8px 0}.bubble small{font-size:.7rem;color:#64748b}.reply-form{padding:18px 24px;border-top:1px solid #e2e8f0;margin-top:auto;display:flex;flex-direction:column;gap:10px}.reply-form>div{display:flex;align-items:center;justify-content:space-between;gap:8px}.reply-form small{color:#64748b}.new-request{padding:28px;display:flex;flex-direction:column;gap:18px}.new-request h2{margin:0}.new-request label span{font-weight:400;color:#64748b}.new-request .primary{align-self:start}.support-error{background:#fef2f2;color:#a12a2a;border-radius:12px;padding:14px;margin-bottom:16px}.empty{padding:30px;color:#64748b;line-height:1.7}.conversation-pane>.empty{margin:auto;text-align:center}.empty h2{font-size:1.3rem}.empty .primary{margin-top:16px}.resolved-note{padding:12px 24px;background:#f0f8f2;color:#346344;font-size:.85rem}.load-more{display:block;margin:6px auto 16px;font-size:.8rem!important}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}
@media(max-width:850px){.support-layout{grid-template-columns:1fr}.thread-list{border-right:0;border-bottom:1px solid #e2e8f0;max-height:280px}.support-heading{align-items:start;flex-direction:column}.support-page.embedded{padding:18px}.support-page{padding:130px 14px 40px}.conversation-header{flex-wrap:wrap}.bubble{max-width:95%}}
</style>
